package com.hbm.entity.mob.maskman;
import com.hbm.entity.projectile.EntityBulletBaseMK4;import com.hbm.weapon.sedna.gun.rifle.RifleBallistics;import com.hbm.registry.HbmSounds;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.entity.ai.goal.Goal;
/** Source no-mutex goal: can fire concurrently with approach/laser. */
final class MaskManMinigunGoal extends Goal {private final MaskMan mob;private LivingEntity target;private int timer=3;MaskManMinigunGoal(MaskMan mob){this.mob=mob;}@Override public boolean canUse(){var e=mob.getTarget();if(e==null||!e.isAlive())return false;target=e;double d=mob.position().distanceTo(target.position());return d>5&&d<10;}@Override public boolean canContinueToUse(){return canUse()||!mob.getNavigation().isDone();}@Override public boolean requiresUpdateEveryTick(){return true;}@Override public void tick(){timer--;if(target!=null)mob.getLookControl().setLookAt(target,15,15);if(timer<=0){timer=3;RifleBallistics.initialize();mob.level().addFreshEntity(new EntityBulletBaseMK4(mob,RifleBallistics.r762_fmj,5,.075F,-1.5,-1.5,0));mob.playSound(HbmSounds.get("weapon.calShoot"),1,1);}}}
